window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["cicd-190-contents-24-pages-38-sections"]={"html":"\r\n\r\n\r\n\r\n\r\n\r\n\r\nStart Here: Foundations, Git &amp; CI — CICD BY Nabawy\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<header><div class=\"wrap\">\r\n☰ Contents · 38\r\n<nav><a href=\"../index.html\">CICD<span> BY Nabawy</span></a>\r\n<span class=\"sep\">/</span>\r\n<span class=\"here\">Start Here: Foundations, Git &amp; CI</span></nav>\r\n<div class=\"search\"><input type=\"search\" /><kbd>⌘K</kbd></div>\r\n<span></span>\r\n<a href=\"../index.html\">← Back</a>\r\n<nav><a href=\"../index.html\">Home</a>\r\n<a href=\"../threads/\">Threads</a>\r\n<a href=\"../tools/\">Tools</a>\r\n</nav>\r\n⛶\r\n◐\r\n☰\r\n</div>\r\n<div class=\"prog\"><b></b></div>\r\n</header>\r\n<div class=\"rlayout\">\r\n<aside><div class=\"toc-head\"><h4 id=\"contents-24-pages-38-sections\">CONTENTS · 24 PAGES · 38 SECTIONS</h4>×</div><a href=\"#p1\">Cover — STARTHERE</a><a href=\"#p2\">Cover — Table of Contents</a><a href=\"#p3\">Cover — 🗺️ The Map — The Whole Route</a><a href=\"#p4\">Cover — What CI/CD Actually Is</a><a href=\"#p5-h1\">1 1 / The CI/CD Lifecycle</a><a href=\"#p5-h2\">2 2 / How to read this manual</a><a href=\"#p6-h1\">3 3 / What Is Continuous Integration</a><a href=\"#p6-h2\">4 4 / What happens without CI/CD</a><a href=\"#p7-h1\">5 5 / CI vs Delivery vs Deployment</a><a href=\"#p8-h1\">6 6 / Anatomy of a Pipeline</a><a href=\"#p8-h2\">7 7 / The Status System</a><a href=\"#p9-h1\">8 8 / Environment Lanes: One Artifact, Three Tracks</a><a href=\"#p9-h2\">9 9 / The Deployment Loop</a><a href=\"#p10-h1\">10 10 / From Push to Pipeline</a><a href=\"#p10-h2\">11 11 / Command and Result</a><a href=\"#p10-h3\">11.1 COMMAND</a><a href=\"#p10-h4\">11.2 RESULT</a><a href=\"#p11-h1\">12 12 / The Artifact Identity</a><a href=\"#p11-h2\">13 13 / The Approval Gate</a><a href=\"#p12-h1\">14 14 / Failure as a State Transition</a><a href=\"#p13-h1\">15 15 / Interview Check</a><a href=\"#p13-h2\">16 16 / The CI/CD System Map</a><a href=\"#p14-h1\">17 01 / What Each Piece Is</a><a href=\"#p14-h2\">18 02 / Why the Gate Exists</a><a href=\"#p15-h1\">19 03 / How the Flow Executes</a><a href=\"#p15-h2\">20 04 / Commands</a><a href=\"#p16-h1\">21 05 / Branching Models</a><a href=\"#p16-h2\">22 06 / Failure Modes &amp;amp; Best Practices</a><a href=\"#p17-h1\">23 07 / Interview Check</a><a href=\"#p17-h2\">24 08 / Handoff</a><a href=\"#p18-h1\">25 01 / The Three Habits</a><a href=\"#p19-h1\">26 02 / PR Gates &amp;amp; Merge Queues</a><a href=\"#p19-h2\">27 03 / Trunk Discipline</a><a href=\"#p20-h1\">28 04 / Handoff</a><a href=\"#p21\">Cover — 📇 Quick Revision — Terms Table</a><a href=\"#p22\">Cover — 🎤 Concept Questions — Distilled Answers</a><a href=\"#p23\">Cover — 📌 Command Cheat Sheet</a><a href=\"#p24\">Cover — 🧪 Self-Quiz + Answer Key</a>\r\n</aside><div class=\"tocscrim\"></div>\r\n<main><div class=\"readbody\">\r\n\r\n\r\n<div class=\"sheet cover\"><div class=\"band\"><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div></div><div class=\"ckick\">SIGNAL SERIES · START HERE</div><h1 id=\"starthere\">START<br /><br />HERE</h1><div class=\"sub\">Foundations, Git and CI — the ground everything stands on.</div><div class=\"byline\">By <span class=\"sig\">Nabawy</span><small>AUTHOR &amp; COMPILER</small></div><div class=\"vols\"><div class=\"volcard on\">Foundations</div><div class=\"volcard\">Source Control</div><div class=\"volcard\">Integration</div></div><div class=\"cver\">V4 · 2026 · START HERE · verified 2026-09-18</div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Contents</div><h1 id=\"table-of-contents\">Table of Contents</h1></div><span class=\"hmeta\">22 sheets</span></div></div><div class=\"tocgrid\"><a href=\"#s02\"><span class=\"tnum\">03</span><span class=\"tp\">🗺️ The Map — The Whole Route</span><span class=\"dots\"></span><span>03</span></a><a href=\"#s02n\"><span class=\"tnum\">03B</span><span class=\"tp\">What CI/CD Actually Is</span><span class=\"dots\"></span><span>03B</span></a><a href=\"#s03\"><span class=\"tnum\">04</span><span class=\"tp\">Foundations</span><span class=\"dots\"></span><span>04</span></a><a href=\"#s04\"><span class=\"tnum\">05</span><span class=\"tp\">Continuous Integration</span><span class=\"dots\"></span><span>05</span></a><a href=\"#s05\"><span class=\"tnum\">06</span><span class=\"tp\">CI vs CD · Delivery vs Deployment</span><span class=\"dots\"></span><span>06</span></a><a href=\"#s06\"><span class=\"tnum\">07</span><span class=\"tp\">Pipeline &amp; Status</span><span class=\"dots\"></span><span>07</span></a><a href=\"#s07\"><span class=\"tnum\">08</span><span class=\"tp\">Environments &amp; Flow</span><span class=\"dots\"></span><span>08</span></a><a href=\"#s08\"><span class=\"tnum\">09</span><span class=\"tp\">Console</span><span class=\"dots\"></span><span>09</span></a><a href=\"#s09\"><span class=\"tnum\">10</span><span class=\"tp\">Artifact &amp; Gate</span><span class=\"dots\"></span><span>10</span></a><a href=\"#s10\"><span class=\"tnum\">11</span><span class=\"tp\">Failure &amp; Recovery</span><span class=\"dots\"></span><span>11</span></a><a href=\"#s11\"><span class=\"tnum\">12</span><span class=\"tp\">Check &amp; Map</span><span class=\"dots\"></span><span>12</span></a><a href=\"#s12\"><span class=\"tnum\">13</span><span class=\"tp\">Source Control</span><span class=\"dots\"></span><span>13</span></a><a href=\"#s13\"><span class=\"tnum\">14</span><span class=\"tp\">Flow &amp; Commands</span><span class=\"dots\"></span><span>14</span></a><a href=\"#s14\"><span class=\"tnum\">15</span><span class=\"tp\">Models &amp; Discipline</span><span class=\"dots\"></span><span>15</span></a><a href=\"#s15\"><span class=\"tnum\">16</span><span class=\"tp\">Check &amp; Handoff</span><span class=\"dots\"></span><span>16</span></a><a href=\"#s16\"><span class=\"tnum\">17</span><span class=\"tp\">Integration</span><span class=\"dots\"></span><span>17</span></a><a href=\"#s17\"><span class=\"tnum\">18</span><span class=\"tp\">Gates</span><span class=\"dots\"></span><span>18</span></a><a href=\"#s18\"><span class=\"tnum\">19</span><span class=\"tp\">Handoff</span><span class=\"dots\"></span><span>19</span></a><a href=\"#s19\"><span class=\"tnum\">20</span><span class=\"tp\">📇 Quick Revision — Terms Table</span><span class=\"dots\"></span><span>20</span></a><a href=\"#s20\"><span class=\"tnum\">21</span><span class=\"tp\">🎤 Concept Questions — Distilled Answers</span><span class=\"dots\"></span><span>21</span></a><a href=\"#s21\"><span class=\"tnum\">22</span><span class=\"tp\">📌 Command Cheat Sheet</span><span class=\"dots\"></span><span>22</span></a><a href=\"#s22\"><span class=\"tnum\">23</span><span class=\"tp\">🧪 Self-Quiz + Answer Key</span><span class=\"dots\"></span><span>23</span></a></div><div class=\"taskhead\">How to use this book <span class=\"hst\">legend</span></div><div class=\"lgd\"><div><span class=\"dot8\"></span>NOTE · context</div><div><span class=\"dot8\"></span>KEY · must retain</div><div><span class=\"dot8\"></span>WATCH OUT · gotcha</div><div><span class=\"dot8\"></span>VERIFIED · check</div></div><div class=\"mark m-tip\"><span class=\"tag\">NOTE</span>Read cover to cover once, then use the Contents to jump. Every chapter ends with a 🎓 EXAM box — if you can answer it cold, move on.</div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 2 —</span><span><a href=\"#toc\">▤ TOC</a> <a href=\"#s02\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"the-map-the-whole-route\">🗺️ The Map — The Whole Route</h1></div><span class=\"hmeta\">MAP</span></div></div><p>Three chapters, one line: <a href=\"#s02\">Foundations</a> draws the pipeline every merge travels; <a href=\"#s11\">Source Control</a> builds the gate that guards it; <a href=\"#s15\">Integration</a> turns the gate into daily discipline.</p><div class=\"zone\"><div class=\"frow\"><span class=\"chipr\">FOUNDATIONS <small>lifecycle</small></span><span class=\"harrow\">──►</span><span class=\"chipr\">SOURCE CONTROL <small>gate</small></span><span class=\"harrow\">──►</span><span class=\"chipr\">INTEGRATION <small>discipline</small></span></div><div class=\"dnote\">commit → verify → merge → repeat</div></div><div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Small merges, verified automatically, fixed immediately — that discipline feeds every pipeline downstream.</div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"what-ci-cd-actually-is\">What CI/CD Actually Is</h1></div><span class=\"hmeta\">03B</span></div></div>\r\n<p>CI/CD is automation plus discipline: every commit verified by machines, every release decided by policy. One line: commit → CI → artifact → CD → observe.</p>\r\n<div class=\"zone\"><div class=\"frow\"><span class=\"chipr\">COMMIT <small>push</small></span><span class=\"harrow\">──►</span><span class=\"chipr\">CI <small>verify</small></span><span class=\"harrow\">──►</span><span class=\"chipr\">ARTIFACT <small>freeze</small></span><span class=\"harrow\">──►</span><span class=\"chipr\">CD <small>decide</small></span><span class=\"harrow\">──►</span><span class=\"chipr\">OBSERVE <small>learn</small></span></div><div class=\"dnote\">green travels forward, red stops the line, feedback flows back</div></div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table><tr><th>Practice</th><th>Question it answers</th></tr><tr><td>Continuous Integration</td><td>Does this change work — build, test, scan green?</td></tr><tr><td>Continuous Delivery</td><td>Is it releasable — staged auto, prod by approval?</td></tr><tr><td>Continuous Deployment</td><td>Did it ship — prod automatic, rollback armed?</td></tr><tr><td>GitOps</td><td>Is reality matching git — pull, drift-corrected?</td></tr></table></div></div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>CI answers does-it-work; Delivery keeps it releasable; Deployment ships it.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Name which gate each change passed: CI gate on merge, approval gate on release, sync gate on deploy.</div>\r\n<p>⏭️ Next: <a href=\"#s03\">Foundations</a></p><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 4b —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s02\">Prev</a> <a href=\"#s03\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"foundations\">Foundations</h1></div><span class=\"hmeta\">04</span></div></div>\r\n<p>A pipeline is not magic.<br /><br />It is a <em>deterministic sequence of machines making decisions about your code</em> — from the moment you push to the moment users feel the change.</p>\r\n<h3 id=\"p5-h1\"><span class=\"n\">1 /</span> The CI/CD Lifecycle</h3>\r\n<div class=\"life\">\r\n<div class=\"lnode\"><img alt=\"Code\" src=\"../assets/icons/git/git.svg\" /><b>CODE</b><small>commit</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode\"><img alt=\"Build\" src=\"../assets/icons/ci-cd/hammer.svg\" /><b>BUILD</b><small>compile</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode\"><img alt=\"Test\" src=\"../assets/icons/testing/flask-conical.svg\" /><b>TEST</b><small>verify</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode art\"><img alt=\"Artifact\" src=\"../assets/icons/general/package.svg\" /><b>ARTIFACT</b><small>freeze</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode\"><img alt=\"Release\" src=\"../assets/icons/ci-cd/workflow.svg\" /><b>RELEASE</b><small>approve</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode\"><img alt=\"Deploy\" src=\"../assets/icons/deployment/rocket.svg\" /><b>DEPLOY</b><small>run</small></div>\r\n</div>\r\n<div class=\"cap\">Every chapter of this manual lives somewhere on this line. Feedback flows backward: deploy → observe → next commit.</div>\r\n<h3 id=\"p5-h2\"><span class=\"n\">2 /</span> How to read this manual</h3>\r\n<p>Each concept answers <b>WHAT · WHY · WHEN · HOW · WHAT CAN FAIL</b>. Green means passed, red means failed, amber means a human must decide, purple means artifact. Color always pairs with a symbol and a label — the book survives grayscale printing.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>DevOps is the culture of shared ownership; CI/CD is its automation — small merges verified on every push, releasable always, deployed by decision.</div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 4 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s02n\">Prev</a> <a href=\"#s04\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"continuous-integration\">Continuous Integration</h1></div><span class=\"hmeta\">05</span></div></div>\r\n<h3 id=\"p6-h1\"><span class=\"n\">3 /</span> What Is Continuous Integration</h3>\r\n<div class=\"iconrow\"><img alt=\"Git\" src=\"../assets/icons/git/git.svg\" /><p><b>Developers merge small changes into shared <span class=\"mono\">main</span> frequently; every merge triggers an automated build + test + scan.</b> CI answers one question: <i>does this change work?</i></p></div>\r\n<p><b>WHEN</b> — on every push and every pull request. <b>HOW</b> — a pipeline job checks out the exact commit, builds it in a clean environment, and reports green or red back to the branch in minutes.</p>\r\n<div class=\"mark m-tip\"><span class=\"tag\">WHY THIS EXISTS </span><p>Without automated integration, a broken change travels for days before anyone discovers it. CI moves that discovery to within minutes of the commit — when the author still remembers what they did.</p></div>\r\n<h3 id=\"p6-h2\"><span class=\"n\">4 /</span> What happens without CI/CD</h3>\r\n<ul>\r\n<li><b>Long-lived branches → merge hell.</b> Weeks of divergent work collide; untangling takes days.</li>\r\n<li><b>\"Works on my machine\" releases.</b> Testing one thing, shipping another — every deploy a gamble.</li>\r\n<li><b>Manual testing → bugs reach users.</b> Humans skip steps under pressure.</li>\r\n<li><b>Manual deploys → release fear.</b> Rare, big, traumatic events nobody runs on Friday.</li>\r\n<li><b>No feedback loop.</b> The same bug class ships again and again.</li>\r\n</ul>\r\n<p>Integration pain is paid <b>minutes per commit</b> with CI/CD, or <b>weeks per release</b> without it.</p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#trunk-discipline\">Trunk Discipline</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 5 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s03\">Prev</a> <a href=\"#s05\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"ci-vs-cd-delivery-vs-deployment\">CI vs CD · Delivery vs Deployment</h1></div><span class=\"hmeta\">06</span></div></div>\r\n<h3 id=\"p7-h1\"><span class=\"n\">5 /</span> CI vs Delivery vs Deployment</h3>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th></th><th>CI</th><th>Continuous Delivery</th><th>Continuous Deployment</th></tr>\r\n<tr><td>Question</td><td>Does it work?</td><td>Could we ship it?</td><td>— (ships itself)</td></tr>\r\n<tr><td>Trigger</td><td>Commit / merge</td><td>Validated artifact</td><td>Validated artifact</td></tr>\r\n<tr><td>Human gate</td><td>No</td><td>Yes — approval</td><td>No</td></tr>\r\n<tr><td>Output</td><td>Verified code</td><td>Releasable artifact</td><td>Production deployment</td></tr>\r\n</table></div></div>\r\n<div class=\"dec\">\r\n<div class=\"q\">DO YOU DEPLOY TO PRODUCTION AUTOMATICALLY?</div>\r\n<div class=\"fork\">\r\n<div class=\"opt y\"><b>YES → CONTINUOUS DEPLOYMENT</b>Every passing change ships. Requires progressive delivery + instant rollback.</div>\r\n<div class=\"opt n\"><b>NO → CONTINUOUS DELIVERY</b>Every passing change is releasable. A human or policy decides when.</div>\r\n</div>\r\n</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">GOTCHA </span><p>A green build does not mean the application works in production. It means only the checks inside that pipeline passed.</p></div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 6 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s04\">Prev</a> <a href=\"#s06\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"pipeline-amp-status\">Pipeline &amp; Status</h1></div><span class=\"hmeta\">07</span></div></div>\r\n<h3 id=\"p8-h1\"><span class=\"n\">6 /</span> Anatomy of a Pipeline</h3>\r\n<div class=\"pipeline\">\r\n<div class=\"stage\"><span class=\"no\">01</span> <img alt=\"Source\" src=\"../assets/icons/git/git.svg\" /><small>● PASSED</small><strong>SOURCE</strong><span class=\"desc\">Git push to main</span> </div><div class=\"connector\">→</div>\r\n<div class=\"stage\"><span class=\"no\">02</span> <img alt=\"Build\" src=\"../assets/icons/ci-cd/hammer.svg\" /><small>● PASSED</small><strong>BUILD</strong><span class=\"desc\">npm ci + build</span> </div><div class=\"connector\">→</div>\r\n<div class=\"stage run\"><span class=\"no\">03</span> <img alt=\"Test\" src=\"../assets/icons/testing/flask-conical.svg\" /><small>● RUNNING</small><strong>TEST</strong><span class=\"desc\">unit + integration</span> </div><div class=\"connector\">→</div>\r\n<div class=\"stage art\"><span class=\"no\">04</span> <img alt=\"Artifact\" src=\"../assets/icons/general/package.svg\" /><small>● WAITING</small><strong>ARTIFACT</strong><span class=\"desc\">image:sha-9f3a</span> </div>\r\n</div>\r\n<p>Stages are phases, jobs are units of work inside them, steps are single operations, runners are the machines. Progression reads left to right; a red stage blocks everything downstream.</p>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Term</th><th>Meaning</th></tr>\r\n<tr><td>Pipeline</td><td>The automated workflow</td></tr>\r\n<tr><td>Stage</td><td>Logical phase (build, test, deploy)</td></tr>\r\n<tr><td>Job</td><td>Unit of executable work inside a stage</td></tr>\r\n<tr><td>Step</td><td>Single operation inside a job</td></tr>\r\n<tr><td>Runner / Agent</td><td>Execution environment running the work</td></tr>\r\n</table></div></div>\r\n<h3 id=\"p8-h2\"><span class=\"n\">7 /</span> The Status System</h3>\r\n<div class=\"status\">\r\n<span class=\"pill\"><i></i>● RUNNING</span>\r\n<span class=\"pill\"><i></i>● PASSED</span>\r\n<span class=\"pill\"><i></i>● FAILED</span>\r\n<span class=\"pill\"><i></i>● BLOCKED</span>\r\n<span class=\"pill\"><i></i>● WAITING</span>\r\n<span class=\"pill\"><i></i>● SKIPPED</span>\r\n</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#controller-agent\">Controllers &amp; Agents</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 7 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s05\">Prev</a> <a href=\"#s07\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"environments-amp-flow\">Environments &amp; Flow</h1></div><span class=\"hmeta\">08</span></div></div>\r\n<h3 id=\"p9-h1\"><span class=\"n\">8 /</span> Environment Lanes: One Artifact, Three Tracks</h3>\r\n<div class=\"lane dev\"><div class=\"lt\"><span>DEVELOPMENT</span> <span>BUILD → TEST</span> </div><div class=\"lb\">push <span class=\"ok\">→ build ✓ → unit tests ✓</span> <span class=\"wt\">→ image staged</span> </div></div>\r\n<div class=\"lane stg\"><div class=\"lt\"><span>STAGING</span> <span>DEPLOY → VERIFY</span> </div><div class=\"lb\">deploy sha-9f3a <span class=\"ok\">→ smoke ✓ → scan ✓</span> <span class=\"wt\">→ awaiting approval</span> </div></div>\r\n<div class=\"lane prd\"><div class=\"lt\"><span>PRODUCTION</span> <span>APPROVE → DEPLOY</span> </div><div class=\"lb\"><span class=\"wt\">◌ approval gate → deploy same digest → observe</span> </div></div>\r\n<h3 id=\"p9-h2\"><span class=\"n\">9 /</span> The Deployment Loop</h3>\r\n<div class=\"vflow\">\r\n<div class=\"fnode good\"><img alt=\"Git\" src=\"../assets/icons/git/git.svg\" /><b>COMMIT</b><small>developer pushes</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode good\"><img alt=\"Pipeline\" src=\"../assets/icons/ci-cd/workflow.svg\" /><b>PIPELINE</b><small>build → test → scan</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode art\"><img alt=\"Artifact\" src=\"../assets/icons/general/package.svg\" /><b>ARTIFACT</b><small>app:sha-9f3a → registry</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode gate\"><b>APPROVAL</b><small>automation stops — a human decides</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode good\"><img alt=\"Deploy\" src=\"../assets/icons/deployment/rocket.svg\" /><b>DEPLOY</b><small>same digest to production</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode\"><img alt=\"Observe\" src=\"../assets/icons/monitoring/activity.svg\" /><b>OBSERVE → FEEDBACK</b><small>metrics → developer → next commit</small></div>\r\n</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a> · <a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 8 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s06\">Prev</a> <a href=\"#s08\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"console\">Console</h1></div><span class=\"hmeta\">09</span></div></div>\r\n<h3 id=\"p10-h1\"><span class=\"n\">10 /</span> From Push to Pipeline</h3>\r\n<pre class=\"code\"><span class=\"p\">$</span> git push origin main<br /><br /><br /><br /><span class=\"c\">→ pipeline triggered · commit 9f3a2c1</span> <br /><br /><br /><br />[01] BUILD     <span class=\"g\">PASSED</span>   1m 12s<br /><br />[02] TEST      <span class=\"b\">RUNNING</span> · 214/300<br /><br />[03] SCAN      <span class=\"w\">WAITING</span> <br /><br />[04] ARTIFACT   <span class=\"w\">WAITING</span> </pre>\r\n<h3 id=\"p10-h2\"><span class=\"n\">11 /</span> Command and Result</h3>\r\n<div class=\"cmdres\">\r\n<div class=\"col\"><h4 id=\"p10-h3\">COMMAND</h4><pre>$ docker build -t registry/app:sha-9f3a .\r\n$ docker push registry/app:sha-9f3a</pre></div>\r\n<div class=\"col\"><h4 id=\"p10-h4\">RESULT</h4><pre>Successfully built 7f91c2\r\nSuccessfully tagged sha-9f3a\r\nPushed digest sha256:4d…e9</pre></div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">WHY IT MATTERS </span> the pushed digest is the frozen, promotable unit. Staging and production deploy this exact hash; nothing is ever rebuilt between environments.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 9 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s07\">Prev</a> <a href=\"#s09\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"artifact-amp-gate\">Artifact &amp; Gate</h1></div><span class=\"hmeta\">10</span></div></div>\r\n<h3 id=\"p11-h1\"><span class=\"n\">12 /</span> The Artifact Identity</h3>\r\n<div class=\"vflow\">\r\n<div class=\"fnode\"><img alt=\"Source code\" src=\"../assets/icons/git/git.svg\" /><b>SOURCE CODE</b><small>repo @ 9f3a2c1</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode\"><img alt=\"Build\" src=\"../assets/icons/ci-cd/hammer.svg\" /><b>BUILD</b><small>npm ci → bundle</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode art\"><img alt=\"Artifact\" src=\"../assets/icons/general/package.svg\" /><b>ARTIFACT · app:sha-9f3a</b><small>Docker image · JAR · binary · Helm chart</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode\"><img alt=\"Registry\" src=\"../assets/icons/general/database.svg\" /><b>REGISTRY</b><small>stored, versioned, distributable</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode\"><img alt=\"Deploy\" src=\"../assets/icons/deployment/rocket.svg\" /><b>DEPLOY</b><small>same digest everywhere</small></div>\r\n</div>\r\n<h3 id=\"p11-h2\"><span class=\"n\">13 /</span> The Approval Gate</h3>\r\n<div class=\"mark m-key\"><span class=\"tag\">AUTOMATED </span> build ✓ · test ✓ · scan ✓ · artifact ✓  →  <b>◌ APPROVAL — a human decision is required</b>  →  <b>PRODUCTION</b></div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">CONTEXT — PRODUCER &amp; CONSUMER </span><p>The build pipeline <b>produces</b> the artifact; the deployment pipeline <b>consumes</b> it; the registry <b>stores</b> it. Lifecycle: build → store → promote → deploy. Anything that breaks this chain — a rebuild, a mutable tag, a skipped gate — voids every check upstream.</p></div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a> · <a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 10 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s08\">Prev</a> <a href=\"#s10\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"failure-amp-recovery\">Failure &amp; Recovery</h1></div><span class=\"hmeta\">11</span></div></div>\r\n<h3 id=\"p12-h1\"><span class=\"n\">14 /</span> Failure as a State Transition</h3>\r\n<div class=\"vflow\">\r\n<div class=\"fnode good\"><img alt=\"Build passed\" src=\"../assets/icons/ci-cd/hammer.svg\" /><b>BUILD ✓</b><small>compiles</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode good\"><img alt=\"Tests passed\" src=\"../assets/icons/testing/flask-conical.svg\" /><b>TEST ✓</b><small>300/300 pass</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode bad\"><img alt=\"Security\" src=\"../assets/icons/security/shield.svg\" /><b>SECURITY ✕</b><small>critical CVE in base image</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode bad\"><img alt=\"Deployment blocked\" src=\"../assets/icons/deployment/rocket.svg\" /><b>DEPLOYMENT BLOCKED</b><small>promotion refused — artifact quarantined</small></div>\r\n</div>\r\n<div class=\"two\">\r\n<div class=\"mark m-fail\"><span class=\"tag\">RECOVERY LOOP </span><p>FAILURE → LOGS → ROOT CAUSE → FIX → NEW COMMIT → PIPELINE. Every incident must land a new check, or it will recur.</p></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">GOTCHA </span><p>Never bypass a red gate with an admin override \"just this once\". The override becomes the process.</p></div>\r\n</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 11 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s09\">Prev</a> <a href=\"#s11\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"check-amp-map\">Check &amp; Map</h1></div><span class=\"hmeta\">12</span></div></div>\r\n<h3 id=\"p13-h1\"><span class=\"n\">15 /</span> Interview Check</h3>\r\n<div class=\"qa\"><span class=\"qn\">Q1</span> <b>Delivery vs Deployment?</b><br /><br /><span class=\"ans\">Delivery keeps software production-ready behind an approval; Deployment releases validated changes automatically.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q2</span> <b>Why must staging and production share one artifact digest?</b><br /><br /><span class=\"ans\">Otherwise you tested one binary and shipped another — verification is void.</span></div>\r\n<h3 id=\"p13-h2\"><span class=\"n\">16 /</span> The CI/CD System Map</h3>\r\n<div class=\"life\">\r\n<div class=\"lnode\"><img alt=\"Source\" src=\"../assets/icons/git/git.svg\" /><b>SOURCE</b><small>commit</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode\"><img alt=\"CI\" src=\"../assets/icons/ci-cd/workflow.svg\" /><b>CI</b><small>build / test</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode art\"><img alt=\"Artifact\" src=\"../assets/icons/general/package.svg\" /><b>ARTIFACT</b><small>digest</small></div><div class=\"lconn\">→</div>\r\n<div class=\"lnode\"><img alt=\"CD\" src=\"../assets/icons/deployment/rocket.svg\" /><b>CD</b><small>release</small></div>\r\n</div>\r\n<div class=\"two\">\r\n<div class=\"mark m-key\"><span class=\"tag\">STAGING </span> → ◌ <b>APPROVAL GATE</b> → <b>PRODUCTION</b></div>\r\n<div class=\"mark m-key\"><span class=\"tag\">OBSERVE </span> → <b>FEEDBACK</b> → next commit</div>\r\n</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>CI/CD in one breath: every merge to <b>main</b> triggers a pipeline that builds, tests and scans in minutes; stages run jobs on runners and produce exactly one <b>immutable artifact digest</b>; <b>Continuous Delivery</b> keeps every change releasable behind an approval, <b>Continuous Deployment</b> ships it; staging and production deploy the <b>same digest</b>; a red gate is never bypassed.</div><p>⏭️ <a href=\"#s11\">⏭️ Next: Source Control</a></p><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a> · <a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 12 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s10\">Prev</a> <a href=\"#s12\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"source-control\">Source Control</h1></div><span class=\"hmeta\">13</span></div></div>\r\n<p>Picking up from <em>Foundations</em>, where a Git push triggered the lifecycle — we now examine the machinery of that trigger: <em>branches isolate work, pull requests gate it, triggers fire pipelines</em>.</p>\r\n<h3 id=\"p14-h1\"><span class=\"n\">01 /</span> What Each Piece Is</h3>\r\n<div class=\"iconrow\"><img alt=\"Git\" src=\"../assets/icons/git/git.svg\" /><p><b>Git</b> — distributed version control; every commit is a snapshot with author, message, parent.</p></div>\r\n<div class=\"iconrow\"><img alt=\"Branch\" src=\"../assets/icons/ci-cd/workflow.svg\" /><p><b>Branching</b> — an independent line of work (<span class=\"mono\">feature/login</span>) forked from <span class=\"mono\">main</span>.</p></div>\r\n<div class=\"iconrow\"><img alt=\"PR\" src=\"../assets/icons/git/github.svg\" /><p><b>Pull Request</b> — a merge proposal combining human review with automated status checks.</p></div>\r\n<div class=\"iconrow\"><img alt=\"Trigger\" src=\"../assets/icons/jenkins/webhook.svg\" /><p><b>CI Trigger</b> — the event that starts a pipeline: PR opened/updated, push to <span class=\"mono\">main</span>, schedule, manual.</p></div>\r\n<h3 id=\"p14-h2\"><span class=\"n\">02 /</span> Why the Gate Exists</h3>\r\n<p>Direct pushes to <span class=\"mono\">main</span> bypass review and verification. The branch → PR → CI → merge flow makes every change <b>Reviewed, Tested, and Traceable</b> before it can break the pipeline.</p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 13 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s11\">Prev</a> <a href=\"#s13\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"flow-amp-commands\">Flow &amp; Commands</h1></div><span class=\"hmeta\">14</span></div></div>\r\n<h3 id=\"p15-h1\"><span class=\"n\">03 /</span> How the Flow Executes</h3>\r\n<div class=\"vflow\">\r\n<div class=\"fnode good\"><img alt=\"Branch\" src=\"../assets/icons/ci-cd/workflow.svg\" /><b>BRANCH</b><small>small logical commits</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode good\"><img alt=\"PR\" src=\"../assets/icons/git/github.svg\" /><b>PULL REQUEST</b><small>trigger fires</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode good\"><img alt=\"Checks\" src=\"../assets/icons/testing/flask-conical.svg\" /><b>CHECKS</b><small>build · test · scan post back</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode good\"><img alt=\"Merge\" src=\"../assets/icons/git/git.svg\" /><b>MERGE</b><small>green + approved only</small></div>\r\n</div>\r\n<h3 id=\"p15-h2\"><span class=\"n\">04 /</span> Commands</h3>\r\n<pre class=\"code\"><span class=\"p\">$</span> git checkout -b feature/login<br /><br /><span class=\"p\">$</span> git add -A &amp;&amp; git commit -m \"feat(auth): add login validation\"<br /><br /><span class=\"p\">$</span> git push -u origin feature/login<br /><br /><br /><br /><span class=\"c\"># then open the PR — CI trigger fires automatically</span></pre>\r\n<pre class=\"code\"><span class=\"c\"># .github/workflows trigger: CI on every PR + push to main</span><br /><br /><span class=\"g\">on:</span><br /><br />  pull_request:<br /><br />  push:<br /><br />    branches: [main]</pre>\r\n<div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 14 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s12\">Prev</a> <a href=\"#s14\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"models-amp-discipline\">Models &amp; Discipline</h1></div><span class=\"hmeta\">15</span></div></div>\r\n<h3 id=\"p16-h1\"><span class=\"n\">05 /</span> Branching Models</h3>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table><tr><th>Model</th><th>Rule</th><th>Best for</th></tr>\r\n<tr><td>GitHub Flow</td><td>Branch → PR → main → deploy</td><td>CD teams (this series' default)</td></tr>\r\n<tr><td>Git Flow</td><td><span class=\"mono\">develop</span> + <span class=\"mono\">release/*</span> + <span class=\"mono\">hotfix/*</span></td><td>Versioned releases</td></tr>\r\n<tr><td>Trunk-Based</td><td>Tiny branches, merge daily</td><td>High-velocity CI</td></tr></table></div></div>\r\n<h3 id=\"p16-h2\"><span class=\"n\">06 /</span> Failure Modes &amp; Best Practices</h3>\r\n<ul><li>Long-lived branches → merge hell; fix with trunk-based discipline.</li><li>Red checks ignored; fix with required status checks.</li><li>Merge-queue races; fix with merge queues, linear history.</li></ul>\r\n<div class=\"mark m-key\"><span class=\"tag\">RULES </span> one logical change per PR (&lt; ~400 lines) · green CI + 1 approval before merge · conventional commits (<span class=\"mono\">feat:</span>, <span class=\"mono\">fix:</span>) so changelogs automate.</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">GOTCHA </span><p>\"Merging equals deploying\" is false. Merging makes a change a <i>candidate</i>; Continuous Delivery decides deployment.</p></div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#trunk-discipline\">Trunk Discipline</a> · <a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 15 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s13\">Prev</a> <a href=\"#s15\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"check-amp-handoff\">Check &amp; Handoff</h1></div><span class=\"hmeta\">16</span></div></div>\r\n<h3 id=\"p17-h1\"><span class=\"n\">07 /</span> Interview Check</h3>\r\n<div class=\"qa\"><span class=\"qn\">Q3</span> <b>Explain the PR as a quality gate.</b><br /><br /><span class=\"ans\">Human review (design) + automated checks (correctness) + merge policy (green + approved = mergeable).</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q4</span> <b>Map the trigger types.</b><br /><br /><span class=\"ans\">Push, pull request, schedule, manual dispatch, tag/release.</span></div>\r\n<h3 id=\"p17-h2\"><span class=\"n\">08 /</span> Handoff</h3>\r\n<p>The trigger fires — now something must execute. This workflow continues in <b>Pipelines, Build, Test &amp; Artifacts</b>, where the triggered pipeline runs build, test, and scan.</p>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Branch small → open a PR → CI verifies → merge on <b>green + approval</b>. <b>Trunk-based</b> is the default: tiny branches, daily merges, flags instead of long branches. <b>Merge queues</b> serialize busy mains; <b>linear history</b> keeps main bisectable. Merging makes a change a <b>candidate</b> — Delivery decides deployment.</div><p>⏭️ <a href=\"#s15\">⏭️ Next: Integration</a></p><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#approval-gates\">Approval Gates</a> · <a href=\"../threads/#trunk-discipline\">Trunk Discipline</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 16 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s14\">Prev</a> <a href=\"#s16\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"integration\">Integration</h1></div><span class=\"hmeta\">17</span></div></div>\r\n<p>Picking up from <em>Source Control</em>, where the PR gate was built — CI is <em>the discipline that makes the gate meaningful</em>: integrate daily, verify automatically, fix immediately.</p>\r\n<h3 id=\"p18-h1\"><span class=\"n\">01 /</span> The Three Habits</h3>\r\n<div class=\"vflow\">\r\n<div class=\"fnode\"><img alt=\"Integrate\" src=\"../assets/icons/git/git.svg\" /><b>INTEGRATE</b><small>branches live hours, never weeks</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode\"><img alt=\"Verify\" src=\"../assets/icons/testing/flask-conical.svg\" /><b>VERIFY</b><small>every merge runs the full gate</small></div><div class=\"farrow\">↓</div>\r\n<div class=\"fnode\"><img alt=\"Fix\" src=\"../assets/icons/ci-cd/workflow.svg\" /><b>FIX</b><small>red main = top priority, stop the line</small></div>\r\n</div>\r\n<p>Integration pain grows with branch age: two-day branches merge in minutes, two-month branches in weeks.</p>\r\n<div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 17 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s15\">Prev</a> <a href=\"#s17\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"gates\">Gates</h1></div><span class=\"hmeta\">18</span></div></div>\r\n<h3 id=\"p19-h1\"><span class=\"n\">02 /</span> PR Gates &amp; Merge Queues</h3>\r\n<ul><li><b>PR gate</b> — required checks + approvals in branch protection. No green, no merge. No admin overrides.</li><li><b>Merge queue</b> — serializes merges on busy <span class=\"mono\">main</span>: rebase onto latest green, re-verify, land. Kills the green-on-branch-red-on-main race.</li><li><b>Linear history</b> — rebase/squash keeps <span class=\"mono\">main</span> bisectable: any commit builds and reverts cleanly.</li></ul>\r\n<h3 id=\"p19-h2\"><span class=\"n\">03 /</span> Trunk Discipline</h3>\r\n<div class=\"mark m-key\"><span class=\"tag\">RULES </span> tiny branches, daily merges · flags hide unfinished work, not long branches · <span class=\"mono\">main</span> always releasable · whoever breaks it fixes it first · measure merges per dev per week.</div>\r\n<ul><li>Long branches → merge hell (WIP limits + flags).</li><li>Red main normalized → quality collapse (stop-the-line culture).</li><li>Flaky gates → bypassed checks (quarantine flakes, never disable gates).</li></ul>\r\n<div class=\"qa\"><span class=\"qn\">Q5</span> <b>CI practice vs CI pipeline?</b><br /><br /><span class=\"ans\">Discipline (merge small, verify, fix first) vs machinery (the pipeline that enforces it).</span></div>\r\n<div class=\"mark m-key\"><span class=\"tag\">DISCIPLINE DETAILS </span> preflight builds validate diffs before landing on <span class=\"mono\">main</span> · rotating build master reverts lingering breakage on large teams · ratcheting gates fail only when warnings or duplication increase.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#trunk-discipline\">Trunk Discipline</a> · <a href=\"../threads/#approval-gates\">Approval Gates</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 18 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s16\">Prev</a> <a href=\"#s18\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"handoff\">Handoff</h1></div><span class=\"hmeta\">19</span></div></div>\r\n<h3 id=\"p20-h1\"><span class=\"n\">04 /</span> Handoff</h3>\r\n<p>Small merges, verified automatically, fixed immediately — that discipline feeds every pipeline downstream. Continue in <b>Pipelines, Build, Test &amp; Artifacts</b>.</p>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>CI is <b>discipline plus machinery</b>: integrate daily, verify every merge automatically, fix a red main first. PR gates, merge queues and required checks enforce it; trunk discipline, flags and a releasable main sustain it. <b>Practice versus pipeline</b>: habits versus the automation that enforces them.</div><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#trunk-discipline\">Trunk Discipline</a></div><div class=\"folio\"><span>📘 Start Here · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 19 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#s17\">Prev</a> <a href=\"#s19\">Next</a></span></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"quick-revision-terms-table\">📇 Quick Revision — Terms Table</h1></div><span class=\"hmeta\">REF</span></div></div><div class=\"tblwrap\"><div class=\"table-scroll\"><table><tr><td><b>Pipeline</b></td><td>The automated workflow from commit to production.</td></tr><tr><td><b>Stage</b></td><td>A logical phase: build, test, scan, deploy.</td></tr><tr><td><b>Job</b></td><td>A unit of executable work inside a stage.</td></tr><tr><td><b>Step</b></td><td>A single operation inside a job.</td></tr><tr><td><b>Runner</b></td><td>The machine executing jobs; agent in Jenkins.</td></tr><tr><td><b>Artifact</b></td><td>Versioned build output: image, JAR, binary.</td></tr><tr><td><b>Digest</b></td><td>Content hash pinning the exact artifact (sha-9f3a).</td></tr><tr><td><b>Registry</b></td><td>Storage and distribution for artifacts.</td></tr><tr><td><b>Promotion</b></td><td>Approving the same artifact for the next environment.</td></tr><tr><td><b>Gate / Check</b></td><td>A required verification before proceeding.</td></tr></table></div></div><div class=\"tblwrap\"><div class=\"table-scroll\"><table><tr><td><b>Merge queue</b></td><td>Serializes merges onto latest green main.</td></tr><tr><td><b>Trunk-based</b></td><td>Tiny branches merged daily; flags hide unfinished work.</td></tr><tr><td><b>Branch</b></td><td>An independent line of work forked from main.</td></tr><tr><td><b>Pull request</b></td><td>Merge proposal coupling human review with CI checks.</td></tr><tr><td><b>Trigger</b></td><td>The event starting a pipeline: push, PR, schedule, manual.</td></tr><tr><td><b>Staging</b></td><td>Prod-like rehearsal; deploys automatic.</td></tr><tr><td><b>Production</b></td><td>Real users; deploys gated or automated.</td></tr><tr><td><b>Approval</b></td><td>The human or policy decision releasing to production.</td></tr><tr><td><b>Continuous Delivery</b></td><td>Every change releasable; deployment is a decision.</td></tr><tr><td><b>Continuous Deployment</b></td><td>Every passing change ships by itself.</td></tr></table></div></div><div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Cover the right column and define each term aloud. Any stumble goes back to its chapter.</div><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#controller-agent\">Controllers &amp; Agents</a> · <a href=\"../threads/#artifact-digest\">Artifact Digest</a> · <a href=\"../threads/#approval-gates\">Approval Gates</a></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"concept-questions-distilled-answers\">🎤 Concept Questions — Distilled Answers</h1></div><span class=\"hmeta\">REF</span></div></div><div class=\"grid2\"><div class=\"qa\"><span class=\"qn\">Q1</span> <b>Delivery vs Deployment?</b><br /><br /><span class=\"ans\">Delivery keeps software production-ready behind an approval; Deployment releases validated changes automatically.</span></div><div class=\"qa\"><span class=\"qn\">Q2</span> <b>Why must staging and production share one artifact digest?</b><br /><br /><span class=\"ans\">Otherwise you tested one binary and shipped another — verification is void.</span></div><div class=\"qa\"><span class=\"qn\">Q3</span> <b>Explain the PR as a quality gate.</b><br /><br /><span class=\"ans\">Human review for design plus automated checks for correctness plus merge policy: green and approved equals mergeable.</span></div><div class=\"qa\"><span class=\"qn\">Q4</span> <b>Name the trigger types.</b><br /><br /><span class=\"ans\">Push, pull request, schedule, manual dispatch, tag or release.</span></div><div class=\"qa\"><span class=\"qn\">Q5</span> <b>CI practice vs CI pipeline?</b><br /><br /><span class=\"ans\">Discipline — merge small, verify, fix first — versus machinery: the pipeline that enforces it.</span></div><div class=\"qa\"><span class=\"qn\">Q6</span> <b>What causes merge hell, and what fixes it?</b><br /><br /><span class=\"ans\">Long-lived divergent branches; trunk-based discipline with tiny daily merges and flags.</span></div><div class=\"qa\"><span class=\"qn\">Q7</span> <b>A green build passed. Does the app work in production?</b><br /><br /><span class=\"ans\">Not necessarily — it means only the checks inside that pipeline passed.</span></div><div class=\"qa\"><span class=\"qn\">Q8</span> <b>Trunk-based vs Git Flow?</b><br /><br /><span class=\"ans\">Trunk: branch to PR to main to deploy, for CD teams. Git Flow: develop plus release branches, for versioned releases.</span></div><div class=\"qa star\"><span class=\"qn\">Q9</span> <b>⭐ Tell me about a checkout that broke main. What did you change?</b><br /><br /><span class=\"ans\">STAR story: red main on a Friday deploy — stopped the line, reverted first, then landed a required check so the class of breakage can never merge again.</span></div></div><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#approval-gates\">Approval Gates</a> · <a href=\"../threads/#trunk-discipline\">Trunk Discipline</a> · <a href=\"../threads/#artifact-digest\">Artifact Digest</a></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"command-cheat-sheet\">📌 Command Cheat Sheet</h1></div><span class=\"hmeta\">REF</span></div></div><div class=\"taskhead\">Git</div><div class=\"tblwrap\"><div class=\"table-scroll\"><table><tr><td><code>git checkout -b feat/x</code></td><td>short branch, merge daily</td></tr><tr><td><code>git push -u origin feat/x</code></td><td>publish + trigger CI</td></tr><tr><td><code>gh pr create --fill</code></td><td>PR with CI gate</td></tr></table></div></div><div class=\"taskhead\">Docker</div><div class=\"tblwrap\"><div class=\"table-scroll\"><table><tr><td><code>docker build -t registry/app:SHA .</code></td><td>versioned image</td></tr><tr><td><code>docker push registry/app:SHA</code></td><td>same digest everywhere</td></tr></table></div></div><div class=\"mark m-tip\"><span class=\"tag\">NOTE</span>Diagnostic order: red gate first — read the failing check, reproduce locally, fix, re-verify. Never bypass.</div><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a></div></div><div class=\"sheet\"><div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">START HERE</div><h1 id=\"self-quiz-answer-key\">🧪 Self-Quiz + Answer Key</h1></div><span class=\"hmeta\">REF</span></div></div><div class=\"grid2\"><div class=\"qa\"><span class=\"qn\">Q1</span> <b>What single question does CI answer?</b></div><div class=\"qa\"><span class=\"qn\">Q2</span> <b>Name the six pipeline stages in order.</b></div><div class=\"qa\"><span class=\"qn\">Q3</span> <b>What makes an artifact promotable?</b></div><div class=\"qa\"><span class=\"qn\">Q4</span> <b>Green plus approved equals…</b></div><div class=\"qa\"><span class=\"qn\">Q5</span> <b>What does a merge queue kill?</b></div><div class=\"qa\"><span class=\"qn\">Q6</span> <b>Flags hide unfinished work instead of…</b></div><div class=\"qa\"><span class=\"qn\">Q7</span> <b>Who fixes a red main, and when?</b></div><div class=\"qa\"><span class=\"qn\">Q8</span> <b>Delivery vs Deployment in one line each?</b></div></div><div class=\"zone\"><div class=\"taskhead\">Answer key</div><ol><li>Does this change work?</li><li>Source, build, test, artifact, release, deploy.</li><li>An immutable digest stored versioned in a registry.</li><li>Mergeable.</li><li>The green-on-branch-red-on-main race.</li><li>Long branches.</li><li>Whoever broke it — first, before anything else.</li><li>Delivery: releasable behind a decision. Deployment: shipped automatically.</li></ol></div><div class=\"mark m-key\"><span class=\"tag\">FINAL CHECK</span>Eight for eight from memory, twice in a row — the foundations are yours. Open <b>Pipelines, Build, Test &amp; Artifacts</b> next.</div><div class=\"trav\"><span>Threads: </span><a href=\"../threads/#artifact-digest\">Artifact Digest</a> · <a href=\"../threads/#trunk-discipline\">Trunk Discipline</a></div></div>\r\n\r\n<div class=\"relatedbox\"><h4 id=\"related-books\">Related books</h4><ul><li><span class=\"rel-icon\"></span><span class=\"rel-main\"><a href=\"jenkins-complete.html\">Jenkins Complete</a><span class=\"rel-meta\">345 min · <span class=\"difbadge int\">Int</span></span><span class=\"rel-why\">→ Follow-up</span></span></li><li><span class=\"rel-icon\"></span><span class=\"rel-main\"><a href=\"labs-handbook.html\">Labs Handbook</a><span class=\"rel-meta\">675 min · <span class=\"difbadge int\">Int</span></span><span class=\"rel-why\">→ Follow-up</span></span></li><li><span class=\"rel-icon\"></span><span class=\"rel-main\"><a href=\"build-artifacts.html\">Pipelines, Build, Test &amp; Artifacts</a><span class=\"rel-meta\">130 min · <span class=\"difbadge int\">Int</span></span><span class=\"rel-why\">→ Follow-up</span></span></li><li><span class=\"rel-icon\"></span><span class=\"rel-main\"><a href=\"cheatsheet.html\">Command Cheatsheet</a><span class=\"rel-meta\">15 min · <span class=\"difbadge beg\">Beg</span></span><span class=\"rel-why\">→ More to explore</span></span></li></ul></div>\r\n<div class=\"chapnav\"><span></span><span></span></div>\r\n</div></main>\r\n<div><img alt=\"Enlarged diagram\" /></div>\r\n</div>\r\n↑\r\n<div class=\"drawer\"><div class=\"scrim\"></div><div class=\"panel\">×\r\n<h3 id=\"menu\">Menu</h3>\r\n<div class=\"setrow mobile-controls\"><a href=\"../index.html\">← Back</a> ⛶<a href=\"../index.html\">Home</a>◐</div>\r\n<div class=\"setrow mobile-search\">Find in this book<input type=\"search\" /></div>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n</div></div>\r\n<div>◐<span>0%</span>⛶ Exit</div>⛶\r\n\r\n\r\n","toc":[{"id":"contents-24-pages-38-sections","text":"CONTENTS · 24 PAGES · 38 SECTIONS","level":4},{"id":"starthere","text":"STARTHERE","level":1},{"id":"table-of-contents","text":"Table of Contents","level":1},{"id":"the-map-the-whole-route","text":"🗺️ The Map — The Whole Route","level":1},{"id":"what-ci-cd-actually-is","text":"What CI/CD Actually Is","level":1},{"id":"foundations","text":"Foundations","level":1},{"id":"1-the-ci-cd-lifecycle","text":"1 / The CI/CD Lifecycle","level":3},{"id":"2-how-to-read-this-manual","text":"2 / How to read this manual","level":3},{"id":"continuous-integration","text":"Continuous Integration","level":1},{"id":"3-what-is-continuous-integration","text":"3 / What Is Continuous Integration","level":3},{"id":"4-what-happens-without-ci-cd","text":"4 / What happens without CI/CD","level":3},{"id":"ci-vs-cd-delivery-vs-deployment","text":"CI vs CD · Delivery vs Deployment","level":1},{"id":"5-ci-vs-delivery-vs-deployment","text":"5 / CI vs Delivery vs Deployment","level":3},{"id":"pipeline-amp-status","text":"Pipeline &amp; Status","level":1},{"id":"6-anatomy-of-a-pipeline","text":"6 / Anatomy of a Pipeline","level":3},{"id":"7-the-status-system","text":"7 / The Status System","level":3},{"id":"environments-amp-flow","text":"Environments &amp; Flow","level":1},{"id":"8-environment-lanes-one-artifact-three-tracks","text":"8 / Environment Lanes: One Artifact, Three Tracks","level":3},{"id":"9-the-deployment-loop","text":"9 / The Deployment Loop","level":3},{"id":"console","text":"Console","level":1},{"id":"10-from-push-to-pipeline","text":"10 / From Push to Pipeline","level":3},{"id":"11-command-and-result","text":"11 / Command and Result","level":3},{"id":"command","text":"COMMAND","level":4},{"id":"result","text":"RESULT","level":4},{"id":"artifact-amp-gate","text":"Artifact &amp; Gate","level":1},{"id":"12-the-artifact-identity","text":"12 / The Artifact Identity","level":3},{"id":"13-the-approval-gate","text":"13 / The Approval Gate","level":3},{"id":"failure-amp-recovery","text":"Failure &amp; Recovery","level":1},{"id":"14-failure-as-a-state-transition","text":"14 / Failure as a State Transition","level":3},{"id":"check-amp-map","text":"Check &amp; Map","level":1},{"id":"15-interview-check","text":"15 / Interview Check","level":3},{"id":"16-the-ci-cd-system-map","text":"16 / The CI/CD System Map","level":3},{"id":"source-control","text":"Source Control","level":1},{"id":"01-what-each-piece-is","text":"01 / What Each Piece Is","level":3},{"id":"02-why-the-gate-exists","text":"02 / Why the Gate Exists","level":3},{"id":"flow-amp-commands","text":"Flow &amp; Commands","level":1},{"id":"03-how-the-flow-executes","text":"03 / How the Flow Executes","level":3},{"id":"04-commands","text":"04 / Commands","level":3},{"id":"models-amp-discipline","text":"Models &amp; Discipline","level":1},{"id":"05-branching-models","text":"05 / Branching Models","level":3},{"id":"06-failure-modes-amp-best-practices","text":"06 / Failure Modes &amp; Best Practices","level":3},{"id":"check-amp-handoff","text":"Check &amp; Handoff","level":1},{"id":"07-interview-check","text":"07 / Interview Check","level":3},{"id":"08-handoff","text":"08 / Handoff","level":3},{"id":"integration","text":"Integration","level":1},{"id":"01-the-three-habits","text":"01 / The Three Habits","level":3},{"id":"gates","text":"Gates","level":1},{"id":"02-pr-gates-amp-merge-queues","text":"02 / PR Gates &amp; Merge Queues","level":3},{"id":"03-trunk-discipline","text":"03 / Trunk Discipline","level":3},{"id":"handoff","text":"Handoff","level":1},{"id":"04-handoff","text":"04 / Handoff","level":3},{"id":"quick-revision-terms-table","text":"📇 Quick Revision — Terms Table","level":1},{"id":"concept-questions-distilled-answers","text":"🎤 Concept Questions — Distilled Answers","level":1},{"id":"command-cheat-sheet","text":"📌 Command Cheat Sheet","level":1},{"id":"self-quiz-answer-key","text":"🧪 Self-Quiz + Answer Key","level":1},{"id":"related-books","text":"Related books","level":4},{"id":"menu","text":"Menu","level":3}],"words":3590,"assets":[]};